	__models__GongNoteShape__00000000_.Identifier = `ref_models.Note01ObstacleMessage`
	__models__GongNoteShape__00000000_.Body = `01. Obstacle Message & Temporality Story

An [models.AIXMBasicMessage] exchanges obstacle datasets via [models.BasicMessageMemberAIXMPropertyType].
Each obstacle feature ([models.VerticalStructureType], [models.ObstacleAreaType]) follows the AIXM Temporality Model:
its lifecycle is represented by [models.VerticalStructureTimeSliceType] slices bounded by ValidTime ([models.TimePrimitivePropertyType]).
`
	__models__GongNoteShape__00000000_.BodyHTML = `<p>01. Obstacle Message &amp; Temporality Story
<p>An <a href="/models#AIXMBasicMessage">models.AIXMBasicMessage</a> exchanges obstacle datasets via <a href="/models#BasicMessageMemberAIXMPropertyType">models.BasicMessageMemberAIXMPropertyType</a>.
Each obstacle feature (<a href="/models#VerticalStructureType">models.VerticalStructureType</a>, <a href="/models#ObstacleAreaType">models.ObstacleAreaType</a>) follows the AIXM Temporality Model:
its lifecycle is represented by <a href="/models#VerticalStructureTimeSliceType">models.VerticalStructureTimeSliceType</a> slices bounded by ValidTime (<a href="/models#TimePrimitivePropertyType">models.TimePrimitivePropertyType</a>).
`
	__models__GongNoteShape__00000000_.X = 40.000000
	__models__GongNoteShape__00000000_.Y = 20.000000
	__models__GongNoteShape__00000000_.Width = 640.000000
	__models__GongNoteShape__00000000_.Height = 142.000000
	__models__GongNoteShape__00000000_.IsHidden = false
