	__models__GongNoteShape__00000000_.IsExpanded = false
	__models__GongNoteShape__00000001_.Name = `02. VerticalStructure & Parts-Note02VerticalStructure`
	__models__GongNoteShape__00000001_.Identifier = `ref_models.Note02VerticalStructure`
	__models__GongNoteShape__00000001_.Body = `02. VerticalStructure & Parts Story

A [models.VerticalStructureTimeSliceType] models man-made or natural obstacles (towers, buildings, wind turbines, cranes).
Each structure is decomposed into [models.VerticalStructurePartType] components (point, line, or polygon geometry)
with operational lighting tracked by [models.VerticalStructureLightingStatusType] and [models.LightElementType].
`
	__models__GongNoteShape__00000001_.BodyHTML = `<p>02. VerticalStructure &amp; Parts Story
<p>A <a href="/models#VerticalStructureTimeSliceType">models.VerticalStructureTimeSliceType</a> models man-made or natural obstacles (towers, buildings, wind turbines, cranes).
Each structure is decomposed into <a href="/models#VerticalStructurePartType">models.VerticalStructurePartType</a> components (point, line, or polygon geometry)
with operational lighting tracked by <a href="/models#VerticalStructureLightingStatusType">models.VerticalStructureLightingStatusType</a> and <a href="/models#LightElementType">models.LightElementType</a>.
`
	__models__GongNoteShape__00000001_.X = 40.000000
	__models__GongNoteShape__00000001_.Y = 20.000000
	__models__GongNoteShape__00000001_.Width = 640.000000
	__models__GongNoteShape__00000001_.Height = 142.000000
