	__models__GongNoteShape__00000002_.Name = `03. ObstacleArea-Note03ObstacleArea`
	__models__GongNoteShape__00000002_.Identifier = `ref_models.Note03ObstacleArea`
	__models__GongNoteShape__00000002_.Body = `03. ObstacleArea Story

An [models.ObstacleAreaTimeSliceType] defines ICAO Annex 15 eTOD obstacle collection surfaces (Area 1, Area 2, Area 3, Area 4).
Its horizontal boundary is modeled by [models.SurfaceType] or 3D [models.ElevatedSurfaceType] along with [models.NoteType] annotations.
`
	__models__GongNoteShape__00000002_.BodyHTML = `<p>03. ObstacleArea Story
<p>An <a href="/models#ObstacleAreaTimeSliceType">models.ObstacleAreaTimeSliceType</a> defines ICAO Annex 15 eTOD obstacle collection surfaces (Area 1, Area 2, Area 3, Area 4).
Its horizontal boundary is modeled by <a href="/models#SurfaceType">models.SurfaceType</a> or 3D <a href="/models#ElevatedSurfaceType">models.ElevatedSurfaceType</a> along with <a href="/models#NoteType">models.NoteType</a> annotations.
`
	__models__GongNoteShape__00000002_.X = 40.000000
