	__models__GongNoteShape__00000003_.Identifier = `ref_models.Note04GroundLight`
	__models__GongNoteShape__00000003_.Body = `04. AeronauticalGroundLight Story

An [models.AeronauticalGroundLightTimeSliceType] describes visual beacons (aerodrome beacons, hazard beacons, marine lighthouses)
located at a 3D [models.ElevatedPointType] and equipped with [models.LightElementType] and [models.LightElementStatusType].
`
	__models__GongNoteShape__00000003_.BodyHTML = `<p>04. AeronauticalGroundLight Story
<p>An <a href="/models#AeronauticalGroundLightTimeSliceType">models.AeronauticalGroundLightTimeSliceType</a> describes visual beacons (aerodrome beacons, hazard beacons, marine lighthouses)
located at a 3D <a href="/models#ElevatedPointType">models.ElevatedPointType</a> and equipped with <a href="/models#LightElementType">models.LightElementType</a> and <a href="/models#LightElementStatusType">models.LightElementStatusType</a>.
`
