	__models__GongNoteShape__00000004_.Name = `05. Elevated 3D Geometry (Point, Curve, Surface)-Note05ElevatedGeometry`
	__models__GongNoteShape__00000004_.Identifier = `ref_models.Note05ElevatedGeometry`
	__models__GongNoteShape__00000004_.Body = `05. Elevated 3D Geometry (Point, Curve, Surface) Story

AIXM extends GML 3.2.1 geometries into [models.ElevatedPointType], [models.ElevatedCurveType], and [models.ElevatedSurfaceType]
to add vertical elevation, vertical datum, and vertical accuracy on top of [models.GeodesicStringType], [models.PolygonPatchType], and [models.DirectPositionListType].
`
	__models__GongNoteShape__00000004_.BodyHTML = `<p>05. Elevated 3D Geometry (Point, Curve, Surface) Story
<p>AIXM extends GML 3.2.1 geometries into <a href="/models#ElevatedPointType">models.ElevatedPointType</a>, <a href="/models#ElevatedCurveType">models.ElevatedCurveType</a>, and <a href="/models#ElevatedSurfaceType">models.ElevatedSurfaceType</a>
to add vertical elevation, vertical datum, and vertical accuracy on top of <a href="/models#GeodesicStringType">models.GeodesicStringType</a>, <a href="/models#PolygonPatchType">models.PolygonPatchType</a>, and <a href="/models#DirectPositionListType">models.DirectPositionListType</a>.
`
